create table public.mail_connection(id uuid primary key default gen_random_uuid(),business_id text not null references public.business_config(business_id) on delete cascade,user_id text not null,provider text not null check(provider in('google','microsoft')),subject text not null,account_email text not null,credentials text not null,expires_at timestamptz not null,enabled boolean not null default true,revision integer not null default 1,started_at timestamptz not null default now(),cursor jsonb,last_sync_at timestamptz,last_error text,lease_until timestamptz not null default 'epoch',lease_id uuid,retry_at timestamptz not null default 'epoch',unique(business_id,provider));
create table public.mail_oauth_attempt(id text primary key,business_id text not null references public.business_config(business_id) on delete cascade,user_id text not null,provider text not null check(provider in('google','microsoft')),cookie_hash text not null,verifier text not null,nonce text not null,return_path text not null check(return_path in('/onboarding','/dashboard/settings/integrations')),expected_revision integer,expires_at timestamptz not null);
create index mail_oauth_expiry on public.mail_oauth_attempt(expires_at);
create table public.contact_proof(id uuid primary key default gen_random_uuid(),business_id text not null references public.business_config(business_id) on delete cascade,channel text not null check(channel in('phone','sms','email','website')),token text not null unique,target text not null,expected_sender text,connection_id uuid,connection_revision integer,started_at timestamptz not null default now(),expires_at timestamptz not null,received_at timestamptz,source_id text,customer_id text,lead_id text,deal_id text,path_confirmed_at timestamptz,reviewed_at timestamptz,next_action text,first_value_at timestamptz,first_value_kind text,first_value_id text,unique(business_id,id));
create index contact_proof_business on public.contact_proof(business_id,started_at desc);
alter table public.mail_connection enable row level security;alter table public.mail_oauth_attempt enable row level security;alter table public.contact_proof enable row level security;revoke all on public.mail_connection,public.mail_oauth_attempt,public.contact_proof from public,anon,authenticated;grant all on public.mail_connection,public.mail_oauth_attempt,public.contact_proof to service_role;
